import{_ as e,H as r,o as s,c as m,aN as t,q as p,s as n,a as l,l as i,aT as c}from"./chunks/framework.D31DlcCL.js";const h="/img/move-objects-basic.svg",g="/img/move-objects-steps.svg",d="/img/move-objects-reverse.svg",A=JSON.parse('{"title":"一年级数学专项：巧移物体（移多补少）图解妙招","description":"“巧移物体”是一年级数学中非常经典的逻辑思维题。如何通过“分一分”、“画一画”让孩子理解移动的奥秘？本文通过直观图解，带你轻松掌握“移多补少”的技巧。","frontmatter":{"title":"一年级数学专项：巧移物体（移多补少）图解妙招","date":"2026-01-18T14:00:00.000Z","categories":["数学"],"tags":["小学数学","一年级","巧移物体","移多补少"],"description":"“巧移物体”是一年级数学中非常经典的逻辑思维题。如何通过“分一分”、“画一画”让孩子理解移动的奥秘？本文通过直观图解，带你轻松掌握“移多补少”的技巧。","cover":"/img/sum-diff-diagram.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-move-objects.md","filePath":"posts/primary-math-move-objects.md","lastUpdated":null}'),u={name:"posts/primary-math-move-objects.md"};function b(_,a,x,k,q,E){const o=r("Mermaid");return s(),m("div",null,[a[1]||(a[1]=t('<h1 id="一年级数学专项-巧移物体-移多补少-图解妙招" tabindex="-1">一年级数学专项：巧移物体（移多补少）图解妙招 <a class="header-anchor" href="#一年级数学专项-巧移物体-移多补少-图解妙招" aria-label="Permalink to &quot;一年级数学专项：巧移物体（移多补少）图解妙招&quot;">​</a></h1><p>在一年级的数学题里，经常会遇到这样的问题：“哥哥有 10 块糖，弟弟有 6 块糖，哥哥给弟弟几块糖，两人的糖就一样多了？”</p><p>这种题目在数学里叫**“巧移物体”<strong>，也叫</strong>“移多补少”**。很多小朋友第一反应是回答“4 块”（因为 10 比 6 多 4），但这其实是个陷阱！</p><p>今天，我们就用**“图解法”**来拆解这个有趣的数学奥秘。</p><hr><h2 id="一、-直观感受-为什么要-移" tabindex="-1">一、 直观感受：为什么要“移”？ <a class="header-anchor" href="#一、-直观感受-为什么要-移" aria-label="Permalink to &quot;一、 直观感受：为什么要“移”？&quot;">​</a></h2><p>我们先用圆圈代表糖果，画出哥哥和弟弟的糖果：</p><p><img src="'+h+'" alt="巧移物体基础概念"></p><p>如果哥哥把多出的 4 个全部给弟弟，会发生什么？</p><ul><li>哥哥剩 6 个。</li><li>弟弟变成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">6 + 4 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 个。</li><li>结果：<strong>还是不一样多，只是变成弟弟比哥哥多了。</strong></li></ul><p><strong>结论</strong>：要把多出来的部分，“分一半”给少的那个人，两人才能平衡。</p><hr><h2 id="二、-核心秘诀-图解三步走" tabindex="-1">二、 核心秘诀：图解三步走 <a class="header-anchor" href="#二、-核心秘诀-图解三步走" aria-label="Permalink to &quot;二、 核心秘诀：图解三步走&quot;">​</a></h2><h3 id="第一步-找差距" tabindex="-1">第一步：找差距 <a class="header-anchor" href="#第一步-找差距" aria-label="Permalink to &quot;第一步：找差距&quot;">​</a></h3><p>先看看多的人比少的人多出几个。</p><blockquote><p><strong>算式：大数 - 小数 = 差距</strong></p></blockquote><h3 id="第二步-分一半" tabindex="-1">第二步：分一半 <a class="header-anchor" href="#第二步-分一半" aria-label="Permalink to &quot;第二步：分一半&quot;">​</a></h3><p>把多出来的部分分成相等的两份。</p><blockquote><p><strong>想一想：几加几等于刚才的差距？</strong></p></blockquote><h3 id="第三步-移过去" tabindex="-1">第三步：移过去 <a class="header-anchor" href="#第三步-移过去" aria-label="Permalink to &quot;第三步：移过去&quot;">​</a></h3><p>把其中一份移给少的人。</p><hr><h2 id="三、-经典例题-画图解题法" tabindex="-1">三、 经典例题：画图解题法 <a class="header-anchor" href="#三、-经典例题-画图解题法" aria-label="Permalink to &quot;三、 经典例题：画图解题法&quot;">​</a></h2><p><strong>【例题 1】</strong> 第一行有 12 朵花，第二行有 4 朵花。从第一行移几多给第二行，两行就一样多了？</p><p><strong>【图解过程】</strong> 我们用图形对齐排列：</p><p><img src="'+g+'" alt="巧移物体步骤图解"></p><ol><li><strong>数一数</strong>：第一行比第二行多出 <strong>8</strong> 朵。</li><li><strong>分一分</strong>：把这 8 朵分成两半，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>=</mo><mn>4</mn><mo>+</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">8 = 4 + 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">4</span></span></span></span>。</li><li><strong>移一移</strong>：把其中 4 朵移到下面。</li></ol>',27)),(s(),p(c,null,{default:n(()=>[i(o,{id:"mermaid-107",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%E7%AC%AC%E4%B8%80%E8%A1%8C%E5%A4%9A%E5%87%BA%208%20%E6%9C%B5%5D%20--%3E%20B%5B%E5%88%86%E6%88%90%204%20%E5%92%8C%204%5D%0A%20%20%20%20B%20--%3E%20C%5B%E7%A7%BB%E8%B5%B0%204%20%E6%9C%B5%5D%0A%20%20%20%20C%20--%3E%20D%5B%E7%BB%93%E6%9E%9C%3A%20%E4%B8%A4%E8%A1%8C%E9%83%BD%E6%98%AF%208%20%E6%9C%B5%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><strong>【答案】</strong>：从第一行移 <strong>4</strong> 朵给第二行。</p><hr><h2 id="四、-进阶变式-反向思考" tabindex="-1">四、 进阶变式：反向思考 <a class="header-anchor" href="#四、-进阶变式-反向思考" aria-label="Permalink to &quot;四、 进阶变式：反向思考&quot;">​</a></h2><p>有时候题目会反过来问：“哥哥给弟弟 3 块糖后，两人的糖一样多，原来哥哥比弟弟多几块？”</p><p><strong>【逻辑分析】</strong> 哥哥给出了 3 块，说明哥哥<strong>少了</strong> 3 块，弟弟<strong>多了</strong> 3 块。</p><p><img src="'+d+'" alt="巧移物体反向逻辑"></p><p>为了让现在一样多，原来哥哥必须比弟弟多出“两个 3 块”。</p><p><strong>【核心公式】</strong></p><ul><li><strong>移动的个数 × 2 = 原来的差距</strong></li></ul><p><strong>【解析】</strong>：原来哥哥比弟弟多 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">3 + 3 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>（块）。</p><hr><h2 id="五、-随堂练习-练一练" tabindex="-1">五、 随堂练习（练一练） <a class="header-anchor" href="#五、-随堂练习-练一练" aria-label="Permalink to &quot;五、 随堂练习（练一练）&quot;">​</a></h2><p><strong>练习 1：基础关</strong> 小明有 14 支铅笔，小红有 8 支。小明给小红几支后，两人的铅笔一样多？ <em>(提示：先算差距，再分一半)</em></p><p><strong>练习 2：思维关</strong> 羊村长把一篮苹果分给喜羊羊和美羊羊。喜羊羊给了美羊羊 5 个苹果后，两只羊的苹果就一样多了。原来喜羊羊比美羊羊多几个苹果？ <em>(提示：移动 5 个，差距是两个 5)</em></p><hr><h2 id="六、-总结口诀" tabindex="-1">六、 总结口诀 <a class="header-anchor" href="#六、-总结口诀" aria-label="Permalink to &quot;六、 总结口诀&quot;">​</a></h2><p>小朋友们，记得这个口诀，巧移物体不发愁：</p><blockquote><p><strong>多出多少先找准，</strong><strong>一分为二对半开。</strong><strong>移走一半给少的，</strong><strong>两边立刻一样多！</strong></p></blockquote><hr><p><em>家长小贴士：在家里可以用围棋子、水果或者积木和孩子一起动手摆一摆。通过真实的“移动”动作，孩子能更快理解为什么是“移动差距的一半”。</em></p>',20))])}const B=e(u,[["render",b]]);export{A as __pageData,B as default};
